{"command":"cd /testbed && python3 -c "
import json
r=json.load(open('revocation_report.json'))
t=json.load(open('revocation_report_template.json'))
def keys(o,p=''):
    if isinstance(o,dict):
        for k,v in o.items(): yield from keys(v,p+'/'+k)
    elif isinstance(o,list):
        for v in o: yield from keys(v,p+'[]')
    else: yield p
rk={k for k in keys(r)}; tk={k for k in keys(t) if '_comment_' not in k}
print('missing:',tk-rk); print('extra:',rk-tk)
print('comment fields left:',[k for k in keys(r) if '_comment_' in k])
print('employees:',len(r['employee_details']),'priv entries:',sum(len(e['privileges']) for e in r['employee_details']))
print(json.dumps(r['summary'],indent=2), r['findings'])
" && echo "--- repo unchanged ---" && md5sum check_revocation.py revocation_report_template.json data/offboarding_list.csv docs/access_management.md README.md && ls -la"}

